process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const KAT='', GAV='';
const DEP=Buffer.from('','base64').toString();
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'uxs2', content:b64}; if(sha) body.sha=sha;
  const pr=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  return pr.status;
}
const putJson=(p,o)=>putRaw(p, Buffer.from(JSON.stringify(o,null,2)).toString('base64'),'uxs2 json');
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await r.json();
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'UXS2'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }

  let s=await snip('TEMP uxs2 set kat', "update_option('ps_uxd_kat','"+KAT+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  s=await snip('TEMP uxs2 set gav', "update_option('ps_uxd_gav','"+GAV+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);

  const sd=await snip('TEMP uxs2 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_uxd2=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  try{ out.deploy=JSON.parse(await resp.text()); }catch(e){ out.deploy_raw='nejson'; }

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e)));
  await page.goto(`${WP}/?ps_uxlog2=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:60000});

  /* 1) KORTELE — pilna, su atributais */
  await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&q=EU221Y`,{waitUntil:'networkidle',timeout:60000});
  await pause(1200);
  const a=await page.$('.pskat-t tbody tr[data-id] a.atv');
  if(a){
    await a.click(); await pause(3500);
    out.kort_textContent_turi_atributus=await page.evaluate(()=>{
      const k=document.querySelector('.kort-turinys'); if(!k) return null;
      return (k.textContent||'').indexOf('Filtravimo atributai')>=0;
    });
    out.atr_blokai=await page.evaluate(()=>{
      const r=[]; document.querySelectorAll('.kort-pane[data-p=apz] .kort-antr').forEach(x=>r.push(x.textContent.trim()));
      return r;
    });
    /* scroll kortele iki atributu bloko ir screenshot */
    await page.evaluate(()=>{
      const bs=document.querySelectorAll('.kort-pane[data-p=apz] .kort-antr');
      for(const b of bs){ if(b.textContent.indexOf('Filtravimo atributai')>=0){ b.scrollIntoView({block:'center'}); return; } }
      const k=document.querySelector('.pskat-kort'); if(k) k.scrollTop=k.scrollHeight*0.55;
    });
    await pause(700);
    let png=await page.screenshot(); out.s_atr=await putRaw('screenshots/uxs2_atributai.png', png.toString('base64'),'uxs2 atr');
  }

  /* 2) SANDELIO SPALVOS — po viena preke is kiekvieno saltinio i viena ekrana */
  const zenklai={};
  for(const sd2 of ['quattro','belcor_tofu','prins','ambrosia']){
    await page.goto(`${WP}/wp-admin/admin.php?page=ps-katalogas&kruva=visos&sand=${sd2}&per=25`,{waitUntil:'networkidle',timeout:60000});
    await pause(900);
    zenklai[sd2]=await page.evaluate(()=>{
      const el=document.querySelector('.pskat-t tbody tr[data-id] .sand');
      if(!el) return null;
      const cs=getComputedStyle(el);
      return {klase:el.className, tekstas:el.textContent.trim(), fonas:cs.backgroundColor, spalva:cs.color};
    });
  }
  out.zenklai=zenklai;
  /* paskutinio (ambrosia) ekrano nuotrauka */
  let png=await page.screenshot(); out.s_sand=await putRaw('screenshots/uxs2_sandeliai.png', png.toString('base64'),'uxs2 sand');

  out.js_klaidos=jsErr.slice(0,6);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await r.json();
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putJson('analize/uxs2.json', out);
}
main().catch(async e=>{ await putJson('analize/uxs2.json',{klaida:String(e),stack:String(e&&e.stack).slice(0,600)}); });
